# example.js

```javascript
import source wasmModule from "./add.wasm";
import {
	add as mathAdd,
	factorial,
	factorialJavascript,
	fibonacci,
	fibonacciJavascript
} from "./math";

const { add } = new WebAssembly.Instance(wasmModule).exports;

console.log(add(22, 2200));
console.log(mathAdd(10, 101));
console.log(factorial(15));
console.log(factorialJavascript(15));
console.log(fibonacci(15));
console.log(fibonacciJavascript(15));
timed("wasm factorial", () => factorial(1500));
timed("js factorial", () => factorialJavascript(1500));
timed("wasm fibonacci", () => fibonacci(22));
timed("js fibonacci", () => fibonacciJavascript(22));

function timed(name, fn) {
	if (!console.time || !console.timeEnd) return fn();
	// warmup
	for (var i = 0; i < 10; i++) fn();
	console.time(name);
	for (var i = 0; i < 5000; i++) fn();
	console.timeEnd(name);
}
```

# math.js

```javascript
import source addWasmModule from "./add.wasm";
import source factorialWasmModule from "./factorial.wasm";
import source fibonacciWasmModule from "./fibonacci.wasm";

export const { add } = new WebAssembly.Instance(addWasmModule).exports;
export const { factorial } = new WebAssembly.Instance(factorialWasmModule).exports;
export const { fibonacci } = new WebAssembly.Instance(fibonacciWasmModule).exports;

export function factorialJavascript(i) {
	if (i < 1) return 1;
	return i * factorialJavascript(i - 1);
}

export function fibonacciJavascript(i) {
	if (i < 2) return 1;
	return fibonacciJavascript(i - 1) + fibonacciJavascript(i - 2);
}
